const e = $input.first().json;
const workflowName = e.workflow?.name || 'неизвестный workflow';
const nodeName = e.execution?.lastNodeExecuted || 'неизвестный узел';
const message = e.execution?.error?.message || JSON.stringify(e).slice(0, 500);

return [{
  json: {
    text: `⚠️ Сбой в автоматизации Pengui\n\nWorkflow: ${workflowName}\nУзел: ${nodeName}\nОшибка: ${message}\n\nЭто не связано с самим Telegram-ботом — просто где-то на сервере что-то не сработало. Загляни в n8n, когда будет момент.`
  }
}];
